class Solution {
public:
    string alienOrder(vector<string>& words) {
        vector<set<int>> g(26);
        vector<int> indeg(26, 0), present(26, 0);
        for (const string& w : words)
            for (char c : w) present[c - 'a'] = 1;
        for (int i = 1; i < (int)words.size(); ++i) {
            const string& a = words[i - 1];
            const string& b = words[i];
            int j = 0;
            while (j < (int)min(a.size(), b.size()) && a[j] == b[j]) ++j;
            if (j == (int)b.size() && a.size() > b.size()) return "";
            if (j < (int)min(a.size(), b.size())) {
                int u = a[j] - 'a', v = b[j] - 'a';
                if (g[u].insert(v).second) ++indeg[v];
            }
        }
        queue<int> q;
        int count = accumulate(present.begin(), present.end(), 0);
        for (int i = 0; i < 26; ++i)
            if (present[i] && indeg[i] == 0) q.push(i);
        string result;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            result.push_back('a' + u);
            for (int v : g[u]) if (--indeg[v] == 0) q.push(v);
        }
        return (int)result.size() == count ? result : "";
    }
};
